function validateGitAuthorIdentity(name, email) {
  const hasName = typeof name === 'string' && name.trim().length >= 2;
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const hasValidEmail = emailRegex.test(email);
  const isValid = hasName && hasValidEmail;
  return {
    authorName: name,
    authorEmail: email,
    isIdentityConfigured: isValid,
    configScope: 'GLOBAL_OR_LOCAL',
    status: isValid ? 'GIT_AUTHOR_IDENTITY_CONFIGURED_NOMINAL' : 'GIT_AUTHOR_IDENTITY_DEFECT'
  };
}

