git_vcs-exam-day-3:
function trackGitFileState(historyState, diskChanged, isStaged) {
  if (historyState === 'NONE' && !isStaged) return { state: 'UNTRACKED', isWorkingTreeClean: false, status: 'FILE_UNTRACKED' };
  if (isStaged && diskChanged) return { state: 'STAGED_AND_MODIFIED', isWorkingTreeClean: false, status: 'FILE_PARTIALLY_STAGED' };
  if (isStaged) return { state: 'STAGED', isWorkingTreeClean: false, status: 'FILE_STAGED_FOR_COMMIT' };
  if (diskChanged) return { state: 'MODIFIED', isWorkingTreeClean: false, status: 'FILE_MODIFIED_UNSTAGED' };
  return { state: 'COMMITTED_CLEAN', isWorkingTreeClean: true, status: 'WORKING_TREE_CLEAN_NOMINAL' };
}

