function parseConventionalCommit(msg) {
  const regex = /^(feat|fix|docs|style|refactor|perf|test|chore)(\([a-z0-9-]+\))?: (.+)$/;
  const match = msg.match(regex);
  if (!match) return { isValid: false, type: null, scope: null, description: null, status: 'CONVENTIONAL_COMMIT_INVALID' };
  return {
    isValid: true,
    type: match[1],
    scope: match[2] ? match[2].replace(/[()]/g, '') : null,
    description: match[3],
    status: 'CONVENTIONAL_COMMIT_VALID_NOMINAL'
  };
}

