function calculateMilestoneProgress(closed, open) {
  const total = closed + open;
  if (total === 0) return { totalIssues: 0, completionPercentage: 0, isSprintComplete: false, status: 'EMPTY_MILESTONE' };
  const pct = Number(((closed / total) * 100).toFixed(1));
  const isDone = open === 0;
  return {
    closedIssues: closed,
    openIssues: open,
    totalIssues: total,
    completionPercentage: pct,
    isSprintComplete: isDone,
    status: isDone ? 'MILESTONE_COMPLETED_NOMINAL' : 'MILESTONE_IN_PROGRESS'
  };
}

