  constructor(timeoutMs = 1000) {
    this.timeout = timeoutMs;
    this.remaining = timeoutMs;
    this.hasReset = false;
  }
  feed() {
    if (this.hasReset) return false;
    this.remaining = this.timeout;
    return true;
  }
  tick(elapsed) {
    if (this.hasReset) return true;
    this.remaining -= elapsed;
    if (this.remaining <= 0) {
      this.hasReset = true;
      this.remaining = 0;
    }
    return this.hasReset;
  }
  isResetTriggered() { return this.hasReset; }
}

