class KalmanFilter1D {
  constructor(processNoiseQ = 0.01, measurementNoiseR = 0.1, estimatedErrorP = 1.0, initialValue = 0) {
    this.q = processNoiseQ;
    this.r = measurementNoiseR;
    this.p = estimatedErrorP;
    this.x = initialValue;
  }
  update(measurement) {
    // Prediction
    this.p = this.p + this.q;
    // Measurement update
    const k = this.p / (this.p + this.r); // Kalman Gain
    this.x = this.x + (k * (measurement - this.x));
    this.p = (1 - k) * this.p;
    return Number(this.x.toFixed(3));
  }
}

