function simulateEvmBytecode(ops) {
  const stack = [];
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    if (op.startsWith('PUSH1_')) {
      const val = parseInt(op.split('_')[1], 10);
      stack.push(val);
    } else if (op === 'ADD') {
      const a = stack.pop(), b = stack.pop();
      stack.push(a + b);
    } else if (op === 'MUL') {
      const a = stack.pop(), b = stack.pop();
      stack.push(a * b);
    } else if (op === 'DUP1') {
      const top = stack[stack.length - 1];
      stack.push(top);
    }
  }
  return {
    finalStackTop: stack[stack.length - 1],
    stackDepth: stack.length,
    stack
  };
}

