function calculateAmmSwapOutput(reserveIn, reserveOut, amountIn, feeBps = 30) {
  const amountInWithFee = amountIn * (10000 - feeBps);
  const numerator = amountInWithFee * reserveOut;
  const denominator = (reserveIn * 10000) + amountInWithFee;
  const amountOut = Math.floor(numerator / denominator);
  const slippagePercent = ((amountIn / (reserveIn + amountIn)) * 100);
  return {
    amountIn,
    amountOut,
    feePaid: Number((amountIn * (feeBps / 1000)).toFixed(2)),
    estimatedSlippagePercent: Number(slippagePercent.toFixed(2))
  };
}

