  const isSolvent = netGain > 0;
  return {
    loanAmount: amount,
    flashLoanFee: fee,
    totalRepaidToPool: totalOwed,
    netArbitrageProfit: Number(netGain.toFixed(2)),
    transactionSuccess: isSolvent,
