}

blockchain-exam-day-20:
function processOraclePrice(round, heartbeat = 3600, now = 1700003000) {
  // round = { answer: 250000000000n, decimals: 8, updatedAt: 1700002000 }
  const isNonZero = round.answer > 0n;
  const isFresh = (now - round.updatedAt) <= heartbeat;
  if (!isNonZero || !isFresh) {
    return { valid: false, error: !isNonZero ? 'ORACLE_PRICE_ZERO' : 'ORACLE_PRICE_STALE_HEARTBEAT_EXPIRED' };
  }
  const normalPrice = Number(round.answer) / (10 ** round.decimals);
  return {
    valid: true,
    usdPrice: normalPrice,
    updatedAt: round.updatedAt,
    status: 'ORACLE_DATA_VERIFIED_AUTHENTIC'
  };
}

