function transformLocalToNdc(point, m, v, p) {
  // 4x4 matrix vector multiply simulator
  const x = point[0], y = point[1], z = point[2], w = 1.0;
  // Model-View-Projection product calculation
  const worldZ = z + 5.0; // Simulated translate
