  } else if (wrap === 'CLAMP_TO_EDGE') {
    return [Math.max(0, Math.min(1, u)), Math.max(0, Math.min(1, v))];
  }
  return [u, v];
}

g3d-exam-day-12:
function computeTbnMatrix(n, t) {
  // Gram-Schmidt orthogonalization: T = normalize(T - dot(T, N) * N)
  const dot = t[0]*n[0] + t[1]*n[1] + t[2]*n[2];
  const tx = t[0] - dot*n[0], ty = t[1] - dot*n[1], tz = t[2] - dot*n[2];
  const tMag = Math.sqrt(tx*tx + ty*ty + tz*tz);
  const tNorm = [tx/tMag, ty/tMag, tz/tMag];
  // Bitangent B = cross(N, T)
  const bx = n[1]*tNorm[2] - n[2]*tNorm[1];
  const by = n[2]*tNorm[0] - n[0]*tNorm[2];
  const bz = n[0]*tNorm[1] - n[1]*tNorm[0];
  return { tangent: tNorm, bitangent: [bx, by, bz], normal: n };
}

