function deformSkinVertex(basePos, indices, weights, matrices) {
  let skinnedX = 0, skinnedY = 0, skinnedZ = 0;
  for (let i = 0; i < 4; i++) {
    const w = weights[i];
    if (w <= 0) continue;
    const mat = matrices[indices[i]]; // [tx, ty, tz] translation
    skinnedX += w * (basePos[0] + mat[0]);
    skinnedY += w * (basePos[1] + mat[1]);
    skinnedZ += w * (basePos[2] + mat[2]);
  }
