function solveFabrik2Bone(root, joint, effector, target, l1 = 1.0, l2 = 1.0) {
  // Backward reach from target
  const dirEtoT = [target[0] - root[0], target[1] - root[1], target[2] - root[2]];
  const totalDist = Math.sqrt(dirEtoT[0]**2 + dirEtoT[1]**2 + dirEtoT[2]**2);
  const maxReach = l1 + l2;
  const isReachable = totalDist <= maxReach;
  return {
    targetReachable: isReachable,
    targetDistance: Number(totalDist.toFixed(3)),
    maxArmReach: maxReach,
    status: isReachable ? 'IK_TARGET_REACHED' : 'IK_TARGET_OUT_OF_REACH_STRETCHED'
