function generateParticleInstanceBuffer(count, bounds = 10) {
  const buffer = [];
  for (let i = 0; i < count; i++) {
    const x = ((i * 1.618) % bounds) - (bounds / 2);
    const y = ((i * 2.718) % bounds);
    const z = ((i * 3.141) % bounds) - (bounds / 2);
    const scale = 0.5 + ((i % 5) * 0.1);
    buffer.push(Number(x.toFixed(2)), Number(y.toFixed(2)), Number(z.toFixed(2)), Number(scale.toFixed(2)));
  }
  return {
    totalParticles: count,
    totalFloats: buffer.length,
    rawFloatData: buffer
  };
}

