function generateHeightmapGrid(size = 4, spacing = 1.0) {
  const vertices = [];
  const indices = [];
  for (let z = 0; z < size; z++) {
    for (let x = 0; x < size; x++) {
      const heightY = Math.sin(x * 0.5) * Math.cos(z * 0.5) * 2.0;
      vertices.push(x * spacing, Number(heightY.toFixed(2)), z * spacing);
    }
  }
  for (let z = 0; z < size - 1; z++) {
    for (let x = 0; x < size - 1; x++) {
      const p0 = z * size + x;
      const p1 = p0 + 1;
      const p2 = (z + 1) * size + x;
      const p3 = p2 + 1;
      indices.push(p0, p2, p1, p1, p2, p3);
    }
  }
  return {
    gridResolution: size,
    totalVerticesCount: vertices.length / 3,
    totalTrianglesCount: indices.length / 3,
    status: 'PROCEDURAL_TERRAIN_MESH_GENERATED'
  };
}

