function calculateFsplAndLinkBudget(d, f, txPower, txGain = 2, rxGain = 2, fade = 10) {
  // FSPL = 20*log10(d) + 20*log10(f) + 20*log10(4*pi/c)
  const c = 299792458;
  const fspl = 20 * Math.log10(d) + 20 * Math.log10(f) + 20 * Math.log10((4 * Math.PI) / c);
  const rxPower = txPower + txGain + rxGain - fspl - fade;
  return {
    distanceMeters: d,
    frequencyHz: f,
    pathLossDb: Number(fspl.toFixed(2)),
    receivedPowerDbm: Number(rxPower.toFixed(2)),
    linkStatus: rxPower >= -120 ? 'LINK_BUDGET_FEASIBLE' : 'LINK_BUDGET_CLOSED_SIGNAL_LOST'
  };
}

