function calculateLoraToaMs(sf, bytes, bw = 125000, preamble = 8, cr = 1, explicit = true) {
  const tSym = (Math.pow(2, sf) / bw) * 1000; // Symbol time in ms
  const tPreamble = (preamble + 4.25) * tSym;
  // Payload symbol count formula:
  const de = (sf >= 11) ? 1 : 0; // Low data rate optimization
  const ih = explicit ? 0 : 1;
  const num = 8 * bytes - 4 * sf + 28 + 16 - 20 * ih;
  const denom = 4 * (sf - 2 * de);
  const payloadSyms = 8 + Math.max(Math.ceil(num / denom) * (cr + 4), 0);
  const tPayload = payloadSyms * tSym;
  const totalToa = tPreamble + tPayload;
  return {
    spreadingFactor: sf,
    payloadBytes: bytes,
    timeOnAirMs: Number(totalToa.toFixed(2)),
    preambleDurationMs: Number(tPreamble.toFixed(2))
  };
}

