function encodeCoapHeader(ver = 1, type = 0, tkl = 4, code = '0.01', msgId = 1234) {
  const byte0 = ((ver & 0x03) << 6) | ((type & 0x03) << 4) | (tkl & 0x0F);
  const [codeClass, codeDetail] = code.split('.').map(Number);
  const byte1 = ((codeClass & 0x07) << 5) | (codeDetail & 0x1F);
  const byte2 = (msgId >> 8) & 0xFF;
  const byte3 = msgId & 0xFF;
  const headerBytes = [byte0, byte1, byte2, byte3];
  return {
    version: ver,
    type: type === 0 ? 'CON' : (type === 1 ? 'NON' : 'ACK'),
    codeString: code,
    messageId: msgId,
    headerHex: headerBytes.map(b => b.toString(16).padStart(2, '0')).join(''),
    status: 'COAP_HEADER_PACKED_NOMINAL'
  };
}

