function updateKalmanFilter(xHat, P, z, Q = 0.01, R = 0.1) {
  // Predict:
  const pPredict = P + Q;
  // Update:
  const K = pPredict / (pPredict + R); // Kalman Gain
  const xHatNew = xHat + K * (z - xHat);
  const pNew = (1 - K) * pPredict;
  return {
    filteredEstimate: Number(xHatNew.toFixed(3)),
    newErrorCovariance: Number(pNew.toFixed(4)),
    kalmanGain: Number(K.toFixed(3)),
    status: 'KALMAN_STATE_FILTERED_NOMINAL'
  };
}

