function classifyNearestCentroid(emb, centroids) {
  // centroids = { 'GESTURE_A': [0.1, 0.2], 'GESTURE_B': [0.9, 0.8] }
  let minDistance = Infinity;
  let bestClass = 'UNKNOWN';
  for (const [cls, cEmb] of Object.entries(centroids)) {
    let distSq = 0;
    for (let i = 0; i < emb.length; i++) {
      const diff = emb[i] - cEmb[i];
      distSq += diff * diff;
    }
    const dist = Math.sqrt(distSq);
    if (dist < minDistance) {
      minDistance = dist;
      bestClass = cls;
    }
  }
  return {
    predictedClass: bestClass,
    euclideanDistance: Number(minDistance.toFixed(3)),
    status: 'FEW_SHOT_CENTROID_CLASSIFIED'
  };
}

