  const isKeyValid = (keyBytes === 16 || keyBytes === 32); // AES-128 or AES-256
  const padNeeded = 16 - (payloadBytes % 16);
  const totalEncryptedBytes = payloadBytes + padNeeded;
  const isConfigValid = isIvValid && isKeyValid;
  return {
    pkcs7PaddingBytes: padNeeded,
    totalCiphertextBytes: totalEncryptedBytes,
    isIvValid,
    isKeyValid,
