function calculateDescriptiveStatistics(data) {
  const n = data.length;
  const sum = data.reduce((acc, v) => acc + v, 0);
  const mean = sum / n;
  const sorted = [...data].sort((a, b) => a - b);
  let median = 0;
  if (n % 2 === 1) median = sorted[Math.floor(n / 2)];
  else median = (sorted[n / 2 - 1] + sorted[n / 2]) / 2;
  const sumSqDiff = data.reduce((acc, v) => acc + Math.pow(v - mean, 2), 0);
  const sampleStd = Math.sqrt(sumSqDiff / (n - 1));
  return {
    sampleSize: n,
    mean: Number(mean.toFixed(2)),
    median: Number(median.toFixed(2)),
    sampleStandardDeviation: Number(sampleStd.toFixed(2)),
    status: 'DESCRIPTIVE_STATS_COMPUTED'
  };
}

