function calculateExponentialSmoothing(actuals, alpha = 0.3, initForecast = actuals[0]) {
  let currForecast = initForecast;
  let totalAbsError = 0;
  for (let t = 0; t < actuals.length; t++) {
    const error = Math.abs(actuals[t] - currForecast);
    totalAbsError += error;
    currForecast = alpha * actuals[t] + (1 - alpha) * currForecast;
  }
  const mae = totalAbsError / actuals.length;
  return {
    smoothingConstantAlpha: alpha,
    meanAbsoluteError: Number(mae.toFixed(2)),
    nextPeriodForecast: Number(currForecast.toFixed(2)),
    status: 'EXPONENTIAL_SMOOTHING_COMPUTED'
  };
}

