function evaluateAbTest(nA, cA, nB, cB) {
  const pA = cA / nA;
  const pB = cB / nB;
  const upliftPct = ((pB - pA) / pA) * 100;
  const pPool = (cA + cB) / (nA + nB);
  const se = Math.sqrt(pPool * (1 - pPool) * (1 / nA + 1 / nB));
  const zStat = (pB - pA) / se;
  const isSignificant = Math.abs(zStat) >= 1.96;
  return {
    conversionRateA: Number((pA * 100).toFixed(2)),
    conversionRateB: Number((pB * 100).toFixed(2)),
    relativeUpliftPercent: Number(upliftPct.toFixed(2)),
    zScore: Number(zStat.toFixed(2)),
    isWinnerDeclared: isSignificant && zStat > 0,
    status: 'AB_TEST_EVALUATED'
  };
}

