bcom_ana-exam-day-24:
function runKMeans1D(data, centroids, maxIter = 10) {
  let c = [...centroids];
  for (let iter = 0; iter < maxIter; iter++) {
    const clusters = c.map(() => []);
    data.forEach(pt => {
      let minDist = Infinity;
      let bestIdx = 0;
      c.forEach((cent, idx) => {
        const dist = Math.abs(pt - cent);
        if (dist < minDist) {
          minDist = dist;
          bestIdx = idx;
        }
      });
      clusters[bestIdx].push(pt);
    });
    const newCentroids = clusters.map((cl, idx) => cl.length > 0 ? (cl.reduce((a, b) => a + b, 0) / cl.length) : c[idx]);
    c = newCentroids;
  }
  return {
    convergedCentroids: c.map(v => Number(v.toFixed(2))),
    clusterCount: c.length,
    status: 'K_MEANS_CLUSTERING_CONVERGED'
  };
}

