bcom_dmkt-exam-day-17:
function calculateUShapedAttribution(touchpoints, totalRevenue) {
  const n = touchpoints.length;
  const allocation = {};
  if (n === 1) {
    allocation[touchpoints[0]] = totalRevenue;
  } else if (n === 2) {
    allocation[touchpoints[0]] = totalRevenue * 0.5;
    allocation[touchpoints[1]] = totalRevenue * 0.5;
  } else {
    const firstVal = totalRevenue * 0.40;
    const lastVal = totalRevenue * 0.40;
    const middleTotal = totalRevenue * 0.20;
    const middleCount = n - 2;
    const midVal = middleTotal / middleCount;
    allocation[touchpoints[0]] = firstVal;
    allocation[touchpoints[n - 1]] = lastVal;
    for (let i = 1; i < n - 1; i++) {
      allocation[touchpoints[i]] = (allocation[touchpoints[i]] || 0) + midVal;
    }
  }
  return {
    totalRevenue,
    touchpointsCount: n,
    attributionAllocation: allocation,
    model: 'U_SHAPED_POSITION_BASED_40_20_40',
    status: 'ATTRIBUTION_COMPUTED'
  };
}

