  let commission = 0;
  if (attainmentPct <= 100) {
    commission = variableOte * (attainmentPct / 100);
  } else {
    const baseOte = variableOte;
    const excessPct = attainmentPct - 100;
    const acceleratedCommission = variableOte * (excessPct / 100) * 1.5;
    commission = baseOte + acceleratedCommission;
  }
  const totalEarnings = base + commission;
  return {
    baseSalaryUsd: base,
    variableCommissionUsd: Math.round(commission),
    totalAnnualEarningsUsd: Math.round(totalEarnings),
    isAcceleratorTriggered: attainmentPct > 100,
    status: 'COMPENSATION_COMPUTED'
  };
}

