  const unitCost = gpuCost / transactions;
  const isEfficient = unitCost <= 0.02 && gpuUtil >= 75.0;
  return {
    monthlyGpuCostUsd: gpuCost,
    totalTransactions: transactions,
    unitCostPerQueryDollars: Number(unitCost.toFixed(4)),
    gpuUtilizationPercent: gpuUtil,
    isFinOpsOptimized: isEfficient,
    status: isEfficient ? 'FINOPS_AI_UNIT_ECONOMICS_HIGHLY_OPTIMIZED' : 'GPU_INFRASTRUCTURE_COST_OVERRUN_DETECTED'
  };
}

