excel_viz-exam-day-1:
function parseCellCoordinate(ref) {
  const m = /^([A-Za-z]+)(\d+)$/.exec(ref);
  if (!m) return { colIndex: 0, rowIndex: 0 };
  const letters = m[1].toUpperCase();
  let col = 0;
  for (let i = 0; i < letters.length; i++) {
    col = col * 26 + (letters.charCodeAt(i) - 64);
  }
  return {
    colIndex: col - 1,
    rowIndex: parseInt(m[2], 10) - 1
  };
}

excel_viz-assign-day-1:
function formatCellCoordinate(colIndex, rowIndex) {
  let c = colIndex + 1;
  let letters = '';
  while (c > 0) {
    const rem = (c - 1) % 26;
    letters = String.fromCharCode(65 + rem) + letters;
    c = Math.floor((c - 1) / 26);
  }
  return letters + (rowIndex + 1);
}

