}

excel_viz-exam-day-3:
function shiftCellReference(ref, rowDelta, colDelta) {
  const m = /^(\$?)([A-Za-z]+)(\$?)(\d+)$/.exec(ref);
  if (!m) return ref;
  const colLock = m[1];
  const colLetters = m[2].toUpperCase();
  const rowLock = m[3];
  const rowNum = parseInt(m[4], 10);

  let newLetters = colLetters;
  if (!colLock && colDelta !== 0) {
    let col = 0;
    for (let i = 0; i < colLetters.length; i++) {
      col = col * 26 + (colLetters.charCodeAt(i) - 64);
    }
    col += colDelta;
    let s = '';
    while (col > 0) {
      const rem = (col - 1) % 26;
      s = String.fromCharCode(65 + rem) + s;
      col = Math.floor((col - 1) / 26);
    }
    newLetters = s;
  }

  const newRow = rowLock ? rowNum : (rowNum + rowDelta);
  return colLock + newLetters + rowLock + newRow;
}

