function evaluateStructuredReference(tableRows, formulaExpression) {
  return tableRows.map(row => {
    let expr = formulaExpression;
    for (const [k, v] of Object.entries(row)) {
      expr = expr.replace(new RegExp('\\[@' + k + '\\]', 'g'), String(v));
    }
    const parts = expr.trim().split(/\s+([+\-*\/])\s+/);
    if (parts.length === 3) {
      const a = parseFloat(parts[0]);
      const op = parts[1];
      const b = parseFloat(parts[2]);
      if (op === '+') return a + b;
      if (op === '-') return a - b;
      if (op === '*') return a * b;
      if (op === '/') return a / b;
    }
    return parseFloat(expr);
  });
}

