excel_viz-exam-day-28:
function auditFormulaPrecedentsAndDependents(cellGraph, startCell) {
  const visited = new Set();
  const recStack = new Set();
  let hasCycle = false;

  function dfs(node) {
    visited.add(node);
    recStack.add(node);

    const neighbors = cellGraph[node] || [];
    for (const next of neighbors) {
      if (!visited.has(next)) {
        dfs(next);
      } else if (recStack.has(next)) {
        hasCycle = true;
      }
    }
    recStack.delete(node);
  }

  dfs(startCell);

  return {
    hasCircularRef: hasCycle,
    visitedCells: Array.from(visited)
  };
}

