function calculatePurchaseJournal(grossAmount, tradeDiscountPct, cashDiscountPct) {
  const tradeDiscount = grossAmount * (tradeDiscountPct / 100);
  const invoicePrice = grossAmount - tradeDiscount;
  const cashDiscount = invoicePrice * (cashDiscountPct / 100);
  const netPayable = invoicePrice - cashDiscount;
  return {
    grossAmount,
    tradeDiscount,
    invoicePrice,
    cashDiscount,
    netPayable
  };
}

bcom-accounting-exam-day-4:
function calculateLedgerBalance(name, debits, credits) {
  const dr = debits.reduce((s, a) => s + a, 0);
  const cr = credits.reduce((s, a) => s + a, 0);
  const diff = dr - cr;
  let type = 'NIL_BALANCE';
  if (diff > 0) type = 'DEBIT_BALANCE';
  else if (diff < 0) type = 'CREDIT_BALANCE';
  return {
    accountName: name,
    totalDebit: dr,
    totalCredit: cr,
    closingBalance: Math.abs(diff),
    balanceType: type
  };
}

bcom-accounting-assign-day-4:
function extractLedgerSummary(accounts) {
  let dr = 0, cr = 0;
  for (const a of accounts) {
    if (a.balanceType === 'DEBIT_BALANCE') dr += a.closingBalance;
    if (a.balanceType === 'CREDIT_BALANCE') cr += a.closingBalance;
  }
  return {
    totalDebit: dr,
    totalCredit: cr,
    isBalanced: dr === cr
  };
}

bcom-accounting-exam-day-5:
function executeBookkeepingMasterKernel(transactions) {
  const dr = transactions.reduce((s, t) => s + (t.drAmount || 0), 0);
  const cr = transactions.reduce((s, t) => s + (t.crAmount || 0), 0);
  const isBalanced = Math.abs(dr - cr) < 0.01;
  return {
    totalTransactionsProcessed: transactions.length,
    cumulativeDebits: dr,
    cumulativeCredits: cr,
    booksBalanced: isBalanced,
    engineStatus: 'BOOKKEEPING_MASTER_KERNEL_ACTIVE_NOMINAL'
  };
}

bcom-accounting-assign-day-5:
function auditBatchSettlement(openBalances, transactions) {
  const res = { ...openBalances };
  for (const t of transactions) {
    const acc = t.account;
    if (res[acc] !== undefined) {
      res[acc] = res[acc] + (t.dr || 0) - (t.cr || 0);
    }
  }
  return res;
}

bcom-accounting-exam-day-6:
function balanceCashBook(cIn, cOut, bIn, bOut, contra) {
  let cash = cIn - cOut;
  let bank = bIn - bOut;
  for (const c of contra) {
    if (c.type === 'CASH_DEPOSITED_TO_BANK') {
      cash -= c.amount;
      bank += c.amount;
    } else if (c.type === 'CASH_WITHDRAWN_FROM_BANK') {
      cash += c.amount;
      bank -= c.amount;
    }
  }
  return {
    closingCashBalance: cash,
    closingBankBalance: bank
  };
}

bcom-accounting-assign-day-6:
function calculatePettyCashReplenishment(floatAmount, expenseVouchers) {
  const totalSpent = expenseVouchers.reduce((s, v) => s + v.amount, 0);
  return {
    totalSpent,
    remainingCash: floatAmount - totalSpent,
    replenishmentNeeded: totalSpent
  };
}

bcom-accounting-exam-day-7:
function aggregateSubsidiaryBooks(purchases, sales, pReturns, sReturns) {
  const p = purchases.reduce((s, x) => s + x.amount, 0);
  const s = sales.reduce((s, x) => s + x.amount, 0);
  const pr = pReturns.reduce((s, x) => s + x.amount, 0);
  const sr = sReturns.reduce((s, x) => s + x.amount, 0);
  return {
    totalPurchases: p,
    totalSales: s,
    totalPReturns: pr,
    totalSReturns: sr,
    netPurchases: p - pr,
    netSales: s - sr
  };
}

bcom-accounting-assign-day-7:
function calculateTradeLedgerTotals(openDebtors, sales, collections, sReturns) {
  const closing = openDebtors + sales - collections - sReturns;
  const avg = (openDebtors + closing) / 2;
  return {
    closingDebtors: closing,
    turnoverRatio: sales / avg
  };
}

bcom-accounting-exam-day-8:
function calculateBRS(cashBook, unpresented, uncredited, bankCharges, directDeposits) {
  const adjusted = cashBook + unpresented - uncredited - bankCharges + directDeposits;
  return {
    initialCashBook: cashBook,
    passBookBalance: adjusted,
    status: 'BRS_RECONCILED_SUCCESSFULLY'
  };
}

bcom-accounting-assign-day-8:
function reconcileOverdraftBRS(odCashBook, unpresented, uncredited, interest) {
  const passBook = (-odCashBook) + unpresented - uncredited - interest;
  return {
    passBookOverdraft: -passBook
  };
}

bcom-accounting-exam-day-9:
function validateTrialBalance(ledgerBalances) {
  const dr = ledgerBalances.reduce((s, b) => s + (b.dr || 0), 0);
  const cr = ledgerBalances.reduce((s, b) => s + (b.cr || 0), 0);
  const isMatched = Math.abs(dr - cr) < 0.01;
  return {
    totalDebits: dr,
    totalCredits: cr,
    isMatched,
    differenceAmount: Math.abs(dr - cr),
    trialBalanceChecksum: isMatched ? 'TRIAL_BALANCE_AGREED_NOMINAL' : 'TRIAL_BALANCE_DISCREPANCY_ERROR'
  };
}

bcom-accounting-assign-day-9:
function estimateTrialBalanceDifference(correctAmount, postedAmount, isDebitSide) {
  const variance = Math.abs(correctAmount - postedAmount);
  return {
    variance,
    affectedSide: isDebitSide ? 'DEBIT' : 'CREDIT'
  };
}

bcom-accounting-exam-day-10:
function rectifyErrorsViaSuspense(initialSuspense, corrections) {
  let bal = initialSuspense;
  for (const c of corrections) {
    if (c.type === 'DEBIT_SUSPENSE') bal -= c.amount;
    else if (c.type === 'CREDIT_SUSPENSE') bal += c.amount;
  }
  const isCleared = Math.abs(bal) < 0.01;
  return {
    closingSuspenseBalance: bal,
    isCleared
  };
}

bcom-accounting-assign-day-10:
function calculateCompensatingErrorEffect(underSales, overPurch) {
  const under = underSales + overPurch;
  return {
    profitUnderstatement: under,
    requiresAdjustment: under > 0
  };
}

bcom-accounting-exam-day-11:
function generateDepreciationSchedule(cost, salvage, lifeYears, wdvRatePct, periods) {
  const slm = (cost - salvage) / lifeYears;
  let bv = cost;
  let y1Bv = cost;
  let y2Bv = cost;
  for (let p = 1; p <= periods; p++) {
    const dep = bv * (wdvRatePct / 100);
    bv -= dep;
    if (p === 1) y1Bv = bv;
    if (p === 2) y2Bv = bv;
  }
  return {
    slmAnnualDepreciation: slm,
    wdvYear1BookValue: y1Bv,
    wdvYear2BookValue: y2Bv
  };
}

bcom-accounting-assign-day-11:
function calculateAssetDisposalGainLoss(cost, accDep, proceeds) {
  const bv = cost - accDep;
  const gain = proceeds - bv;
  return {
    bookValue: bv,
    profitOnSale: gain,
    isGain: gain >= 0
  };
}

bcom-accounting-exam-day-12:
function calculateGrossProfit(openStock, purch, pRet, directExp, sales, sRet, closeStock) {
  const netPurch = purch - pRet;
  const netSales = sales - sRet;
  const cogs = openStock + netPurch + directExp - closeStock;
  const gp = netSales - cogs;
  return {
    costOfGoodsSold: cogs,
    grossProfit: gp,
    grossProfitMarginPercent: netSales > 0 ? (gp / netSales) * 100 : 0
  };
}

bcom-accounting-assign-day-12:
function calculateCOGSAndMargin(netSales, grossProfit) {
  const cogs = netSales - grossProfit;
  return {
    cogs,
    marginPct: (grossProfit / netSales) * 100,
    markupPct: (grossProfit / cogs) * 100
  };
}

bcom-accounting-exam-day-13:
function calculateNetProfit(gp, opExp, nonOpInc, nonOpExp, taxPct) {
  const op = gp - opExp;
  const pbt = op + nonOpInc - nonOpExp;
  const tax = pbt > 0 ? pbt * (taxPct / 100) : 0;
  const pat = pbt - tax;
  return {
    operatingProfit: op,
    profitBeforeTax: pbt,
    taxAmount: tax,
    netProfitAfterTax: pat
  };
}

bcom-accounting-assign-day-13:
function calculateExpenseRatios(revenue, adminExp, sellExp, finCosts) {
  return {
    adminRatio: (adminExp / revenue) * 100,
    sellingRatio: (sellExp / revenue) * 100,
    totalOperatingRatio: ((adminExp + sellExp) / revenue) * 100
  };
}

bcom-accounting-exam-day-14:
function marshalBalanceSheet(ca, nca, cl, ncl, eq) {
  const assets = ca + nca;
  const liabEq = cl + ncl + eq;
  return {
    totalAssets: assets,
    totalLiabilitiesAndEquity: liabEq,
    netWorkingCapital: ca - cl,
    isBalanced: Math.abs(assets - liabEq) < 0.01
  };
}

bcom-accounting-assign-day-14:
function evaluateWorkingCapitalHealth(ca, cl, qa) {
  const cr = ca / cl;
  const qr = qa / cl;
  return {
    currentRatio: cr,
    quickRatio: qr,
    isHealthy: cr >= 2.0 && qr >= 1.0
  };
}

bcom-accounting-exam-day-15:
function executeYearEndFinancialStatements(tb, adj) {
  const netSales = tb.sales - (adj.salesReturns || 0);
  const netPurch = tb.purchases - (adj.purchReturns || 0);
  const cogs = tb.openStock + netPurch + tb.directWages - (adj.closingStock || 0);
  const gp = netSales - cogs;
  const adjExp = tb.expenses + (adj.outstandingExp || 0) - (adj.prepaidExp || 0);
  const np = gp - adjExp;
  return {
    grossProfit: gp,
    netProfit: np,
    status: 'FINANCIAL_STATEMENTS_CLOSED_AND_AUDITED'
  };
}

bcom-accounting-assign-day-15:
function reorganizeBalanceSheetOrder(items, orderType) {
  const rank = { 'CASH': 1, 'DEBTORS': 2, 'STOCK': 3, 'PLANT': 4 };
  return [...items].sort((a, b) => {
    const diff = rank[a] - rank[b];
    return orderType === 'LIQUIDITY' ? diff : -diff;
  });
}

bcom-accounting-exam-day-16:
function allocateTallyGroup(ledgerName, category) {
  if (category === 'BANK') return 'Bank Accounts';
  if (category === 'CUSTOMER') return 'Sundry Debtors';
  if (category === 'VENDOR') return 'Sundry Creditors';
  if (category === 'TAX') return 'Duties & Taxes';
  if (category === 'SALARY') return 'Indirect Expenses';
