bcom-accounting-exam-day-17:
function processTallyVoucher(voucherType, drAccs, crAccs, amount) {
  if (voucherType === 'F4_CONTRA') {
    const valid = drAccs.every(a => /Bank|Cash/i.test(a)) && crAccs.every(a => /Bank|Cash/i.test(a));
    return {
      isApproved: valid,
      voucherRef: 'VCH_CONTRA_' + amount
    };
