  return {
    isApproved: true,
    voucherRef: 'VCH_GENERAL_' + amount
  };
}

bcom-accounting-assign-day-17:
function calculateTallyItemInvoice(qty, rate, discPct, gstPct) {
  const gross = qty * rate;
  const disc = gross * (discPct / 100);
  const taxable = gross - disc;
  const tax = taxable * (gstPct / 100);
  return {
    gross,
    taxable,
    tax,
    invoiceTotal: taxable + tax
  };
}

bcom-accounting-exam-day-18:
function calculateGstInvoice(taxableValue, ratePct, supplierState, buyerState) {
  const isIntra = supplierState === buyerState;
  const totalTax = taxableValue * (ratePct / 100);
  let cgst = 0, sgst = 0, igst = 0;
  if (isIntra) {
    cgst = totalTax / 2;
    sgst = totalTax / 2;
  } else {
    igst = totalTax;
  }
  return {
    cgst,
    sgst,
    igst,
    totalTaxAmount: totalTax,
    totalInvoiceAmount: taxableValue + totalTax
  };
}

bcom-accounting-assign-day-18:
function aggregateGstTaxInvoice(items, supplierState, buyerState) {
  let taxable = 0, cgst = 0, sgst = 0, igst = 0;
  const isIntra = supplierState === buyerState;
  for (const it of items) {
    taxable += it.taxableValue;
    const tax = it.taxableValue * (it.gstRatePct / 100);
    if (isIntra) {
      cgst += tax / 2;
      sgst += tax / 2;
    } else {
      igst += tax;
    }
  }
  return {
    totalTaxable: taxable,
    totalCgst: cgst,
    totalSgst: sgst,
    totalIgst: igst,
    grandTotal: taxable + cgst + sgst + igst
  };
}

bcom-accounting-exam-day-19:
function calculateGstItcSetOff(outIgst, outCgst, outSgst, inIgst, inCgst, inSgst) {
  let remInIgst = inIgst;
  let payIgst = outIgst;
  if (remInIgst >= payIgst) {
    remInIgst -= payIgst;
    payIgst = 0;
  } else {
    payIgst -= remInIgst;
    remInIgst = 0;
  }

  let payCgst = outCgst;
  if (remInIgst > 0) {
    if (remInIgst >= payCgst) {
      remInIgst -= payCgst;
      payCgst = 0;
    } else {
      payCgst -= remInIgst;
      remInIgst = 0;
    }
  }

  let paySgst = outSgst;
  if (remInIgst > 0) {
    if (remInIgst >= paySgst) {
      remInIgst -= paySgst;
      paySgst = 0;
    } else {
      paySgst -= remInIgst;
      remInIgst = 0;
    }
  }

  if (inCgst >= payCgst) {
    payCgst = 0;
  } else {
    payCgst -= inCgst;
  }

  if (inSgst >= paySgst) {
    paySgst = 0;
  } else {
    paySgst -= inSgst;
  }

  const totalPay = payIgst + payCgst + paySgst;
  return {
    netPayableIgst: payIgst,
    netPayableCgst: payCgst,
    netPayableSgst: paySgst,
    totalNetCashTaxPayable: totalPay
  };
}

bcom-accounting-assign-day-19:
function evaluateBlockedItc(purchasesList) {
  let blocked = 0, eligible = 0;
  const blockedCategories = ['MOTOR_VEHICLES_PERSONAL', 'FOOD_BEVERAGES', 'CLUB_MEMBERSHIP'];
  for (const it of purchasesList) {
    if (blockedCategories.includes(it.category)) blocked += it.tax;
    else eligible += it.tax;
  }
  return {
    eligibleItc: eligible,
    blockedItc: blocked
  };
}

bcom-accounting-exam-day-20:
function reconcileGstr2b(books, portal) {
  let matched = 0, missing = 0;
  for (const b of books) {
    const found = portal.find(p => p.invoiceNo === b.invoiceNo && p.taxAmount === b.taxAmount);
    if (found) matched++;
    else missing++;
  }
  return {
    matchedInvoicesCount: matched,
    missingIn2bCount: missing,
    status: missing > 0 ? 'INELIGIBLE_ITC_BLOCKED_RULE_36_4' : 'GSTR_2B_FULLY_RECONCILED_COMPLIANT'
  };
}

bcom-accounting-assign-day-20:
function calculateGstr3bLateFeeAndInterest(taxPayable, delayDays, dailyLateFee) {
  const interest = delayDays > 0 ? Number((taxPayable * (0.18 / 365) * delayDays).toFixed(2)) : 0;
  const lateFee = delayDays * dailyLateFee;
  return {
    taxPayable,
    delayDays,
    interest,
    lateFee,
    totalDue: taxPayable + interest + lateFee
  };
}

bcom-accounting-exam-day-21:
function executeEnterpriseGstEngine(invoices, inputCredits) {
