  const net = Math.max(0, outGst - inputCredits);
  return {
    totalOutputGstCollected: outGst,
    netGstPayableToGovt: net,
    engineStatus: 'ENTERPRISE_GST_ENGINE_ACTIVE_NOMINAL'
  };
}

bcom-accounting-assign-day-21:
function detectGstAuditDiscrepancies(gstr1, gstr3b, books) {
