  const diffB = Math.abs(gstr3b - books);
  return {
    diff1_3b: diff1,
    diffBooks: diffB,
    hasRisk: diff1 > 0.01 || diffB > 0.01
  };
}

bcom-accounting-exam-day-22:
function evaluateEwayBillRequirement(value, distanceKm, isInterstate) {
  const isMandatory = value >= 50000;
  const validityDays = isMandatory ? Math.max(1, Math.ceil(distanceKm / 200)) : 0;
  return {
