bcom-accounting-exam-day-23:
function calculatePayrollTakeHome(basic, da, hra, allowances, pt = 200) {
  const gross = basic + da + hra + allowances;
  const epfWages = basic + da;
  const epf = Number((epfWages * 0.12).toFixed(2));
  const esi = gross <= 21000 ? Number((gross * 0.0075).toFixed(2)) : 0;
  const net = gross - epf - esi - pt;
  return {
    grossSalary: gross,
    employeeEpfDeduction: epf,
    employeeEsiDeduction: esi,
    netTakeHomePay: net
  };
}

bcom-accounting-assign-day-23:
function calculateEmployerCtcCost(grossSalary, basicAndDa) {
  const epf = basicAndDa * 0.12;
  const esi = grossSalary <= 21000 ? grossSalary * 0.0325 : 0;
  const gratuity = basicAndDa * 0.0481;
  const totalCost = grossSalary + epf + esi + gratuity;
  return {
    grossSalary,
    employerEpf: epf,
    employerEsi: esi,
    gratuityProvision: Number(gratuity.toFixed(2)),
    totalCtc: Number(totalCost.toFixed(2))
  };
}

bcom-accounting-exam-day-24:
function calculateTdsWithholding(amount, section, isCompany, hasPan = true) {
  if (!hasPan) {
    const tds = amount * 0.20;
    return { tdsWithheld: tds, netPayableToVendor: amount - tds };
  }
  let rate = 0.01;
  if (section === '194C') rate = isCompany ? 0.02 : 0.01;
  else if (section === '194J') rate = 0.10;
  else if (section === '194I') rate = 0.10;
  const tds = amount * rate;
  return {
    tdsWithheld: tds,
    netPayableToVendor: amount - tds
  };
}

bcom-accounting-assign-day-24:
function reconcileForm26AS(booksTds, form26As) {
