  const diff = booksTds - portal;
  return {
    booksTds,
    portalTotal: portal,
    uncreditedTds: Math.max(0, diff),
    isMatched: diff === 0
  };
}

bcom-accounting-exam-day-25:
function compareIncomeTaxRegimes(gross, d80c = 150000, d80d = 25000, homeLoan = 0) {
  // New regime: 75k std deduction. If <= 7L taxable -> 87A rebate = 0 tax
  const newTaxable = Math.max(0, gross - 75000);
  let newTax = 0;
  if (newTaxable > 700000) {
    // slab calculation
    if (newTaxable > 1500000) newTax += (newTaxable - 1500000) * 0.30 + 150000;
    else if (newTaxable > 1200000) newTax += (newTaxable - 1200000) * 0.20 + 90000;
    else if (newTaxable > 1000000) newTax += (newTaxable - 1000000) * 0.15 + 60000;
    else if (newTaxable > 700000) newTax += (newTaxable - 700000) * 0.10 + 30000;
  }

  const oldTaxable = Math.max(0, gross - 50000 - Math.min(150000, d80c) - d80d - homeLoan);
  let oldTax = 0;
  if (oldTaxable > 500000) {
    if (oldTaxable > 1000000) oldTax += (oldTaxable - 1000000) * 0.30 + 112500;
    else oldTax += (oldTaxable - 500000) * 0.20 + 12500;
  }

  return {
    recommendedRegime: newTax < oldTax ? 'NEW_REGIME_115BAC' : 'OLD_REGIME',
    oldRegimeTax: oldTax,
    newRegimeTax: newTax,
    status: 'TAX_REGIME_COMPARISON_OPTIMAL'
  };
}

bcom-accounting-assign-day-25:
function calculateAdvanceTaxInstallments(taxLiability) {
