    totalAdvanceTax: taxLiability
  };
}

bcom-accounting-exam-day-26:
function calculateCapitalGainsAndCorporateTax(ltcg, stcg, corpProfit) {
  const taxableLtcg = Math.max(0, ltcg - 125000);
  const ltcgTax = Math.round(taxableLtcg * 0.125);
  const stcgTax = Math.round(stcg * 0.20);
  const corpTax = Math.round(corpProfit * 0.25168);
  return {
    ltcgTaxPayable: ltcgTax,
    stcgTaxPayable: stcgTax,
    corporateTaxPayable: corpTax
  };
}

bcom-accounting-assign-day-26:
function calculateIndexedCostOfAcquisition(purchasePrice, purchaseCii, saleCii) {
  const indexed = Number((purchasePrice * (saleCii / purchaseCii)).toFixed(2));
  return {
    purchasePrice,
    indexedCost: indexed,
    indexationBenefit: indexed - purchasePrice
  };
}

bcom-accounting-exam-day-27:
function calculateFinancialRatios(ca, inv, cl, debt, eq, np, rev) {
  const cr = Number((ca / cl).toFixed(2));
  const qr = Number(((ca - inv) / cl).toFixed(2));
  const de = Number((debt / eq).toFixed(2));
  const npm = Number(((np / rev) * 100).toFixed(2));
  return {
    currentRatio: cr,
    quickRatio: qr,
    debtToEquityRatio: de,
    netProfitMarginPercent: npm,
    isLiquiditySound: cr >= 1.5 && de <= 2.0
  };
}

bcom-accounting-assign-day-27:
function calculateDuPontROE(netProfit, revenue, assets, equity) {
  const margin = netProfit / revenue;
  const turnover = revenue / assets;
  const leverage = assets / equity;
  const roe = margin * turnover * leverage * 100;
  return {
    profitMargin: margin,
    assetTurnover: turnover,
    financialLeverage: leverage,
    roePercent: Number(roe.toFixed(2))
  };
}

bcom-accounting-exam-day-28:
function calculateCashFlowStatement(np, dep, wcChange, faBuy, faSell, loan, div, openCash) {
  const cfo = np + dep + wcChange;
  const cfi = faSell - faBuy;
  const cff = loan - div;
  const netChange = cfo + cfi + cff;
  return {
    cashFromOperations: cfo,
    cashFromInvesting: cfi,
    cashFromFinancing: cff,
    netChangeInCash: netChange,
    closingCashBalance: openCash + netChange
  };
}

bcom-accounting-assign-day-28:
