bcom-finance-assign-day-1:
function calculateTreasuryAllocation(totalCash, operatingReservePct, capitalGrowthPct) {
  const op = totalCash * (operatingReservePct / 100);
  const gr = totalCash * (capitalGrowthPct / 100);
  const buf = totalCash - op - gr;
  return {
    operatingCash: op,
    growthCash: gr,
    bufferCash: buf
  };
}

bcom-finance-exam-day-2:
function calculateFutureValue(pv, ratePct, years, freq = 1) {
  const r = ratePct / 100;
  let fv = 0;
  if (freq === 'CONTINUOUS') {
    fv = pv * Math.exp(r * years);
  } else {
    fv = pv * Math.pow(1 + r / freq, freq * years);
  }
  const fvRound = Number(fv.toFixed(2));
  return {
    presentValue: pv,
    futureValue: fvRound,
    totalInterest: Number((fvRound - pv).toFixed(2))
  };
}

bcom-finance-assign-day-2:
function estimateDoublingPeriod(ratePct, exact = false) {
  const rule72 = Number((72 / ratePct).toFixed(2));
  const exactY = Number((Math.log(2) / Math.log(1 + ratePct / 100)).toFixed(2));
  return {
    doublingYears: exact ? exactY : rule72,
    rule72Years: rule72,
    exactYears: exactY
  };
}

bcom-finance-exam-day-3:
function calculatePresentValue(cashFlows, discountRatePct) {
  const r = discountRatePct / 100;
  const total = cashFlows.reduce((sum, cf, idx) => sum + cf / Math.pow(1 + r, idx + 1), 0);
  return {
    totalPresentValue: Number(total.toFixed(2)),
    cashFlowCount: cashFlows.length
  };
}

bcom-finance-assign-day-3:
function calculatePerpetuityValue(cashFlow, discountRatePct, growthRatePct = 0) {
  const r = discountRatePct / 100;
  const g = growthRatePct / 100;
  if (r <= g) throw new Error('Discount rate must exceed growth rate');
  const pv = cashFlow / (r - g);
  return {
    presentValue: Number(pv.toFixed(2)),
    isGrowing: growthRatePct > 0
  };
}

bcom-finance-exam-day-4:
function calculateLoanEmi(principal, annualRatePct, tenureMonths) {
  if (annualRatePct === 0) {
    const emi = Number((principal / tenureMonths).toFixed(2));
    return {
      monthlyEmi: emi,
      month1Interest: 0,
      month1Principal: emi,
      totalAmountRepaid: principal
    };
  }
  const mRate = annualRatePct / 12 / 100;
  const pwr = Math.pow(1 + mRate, tenureMonths);
  const emi = Number(((principal * mRate * pwr) / (pwr - 1)).toFixed(2));
  const m1Int = Number((principal * mRate).toFixed(2));
  const m1Prin = Number((emi - m1Int).toFixed(2));
  const totalRepay = Number((emi * tenureMonths).toFixed(2));
  return {
    monthlyEmi: emi,
    month1Interest: m1Int,
    month1Principal: m1Prin,
    totalAmountRepaid: totalRepay
  };
}

bcom-finance-assign-day-4:
function compareAnnuities(payment, ratePct, years, isDue = false) {
  const r = ratePct / 100;
  const fvOrd = payment * ((Math.pow(1 + r, years) - 1) / r);
  const fv = isDue ? fvOrd * (1 + r) : fvOrd;
  return {
    futureValue: Number(fv.toFixed(2)),
    isDue
  };
}

bcom-finance-exam-day-5:
function executeTvmMasterKernel(c0, cfs, rPct, p, emiRate, n) {
  const r = rPct / 100;
  const pvInflows = cfs.reduce((s, cf, i) => s + cf / Math.pow(1 + r, i + 1), 0);
  const surplus = pvInflows - c0;
  let emi = 0;
  if (emiRate > 0 && n > 0 && p > 0) {
    const mRate = emiRate / 12 / 100;
    const pwr = Math.pow(1 + mRate, n);
    emi = (p * mRate * pwr) / (pwr - 1);
  }
  return {
    pvInflows: Number(pvInflows.toFixed(2)),
    netPresentSurplus: Number(surplus.toFixed(2)),
    monthlyEmi: Number(emi.toFixed(2)),
    engineStatus: 'TVM_MASTER_KERNEL_ACTIVE_NOMINAL'
  };
}

bcom-finance-assign-day-5:
