    targetAmount,
    totalInterestEarned: Number((targetAmount - pmt * years).toFixed(2))
  };
}

bcom-finance-exam-day-6:
function calculateBondPrice(faceValue, couponRatePct, yieldPct, years, freq = 1) {
  const c = (faceValue * (couponRatePct / 100)) / freq;
  const y = yieldPct / 100 / freq;
  const n = years * freq;
  const pvCoupons = y === 0 ? c * n : c * ((1 - Math.pow(1 + y, -n)) / y);
  const pvFace = faceValue / Math.pow(1 + y, n);
  const price = Number((pvCoupons + pvFace).toFixed(2));
  let type = 'PAR_BOND';
  if (couponRatePct > yieldPct) type = 'PREMIUM_BOND';
  else if (couponRatePct < yieldPct) type = 'DISCOUNT_BOND';
  return {
    bondPrice: price,
    pricingType: type
  };
}

