bcom-finance-exam-day-8:
function calculateBondDuration(faceValue, couponRatePct, yieldPct, years) {
  const y = yieldPct / 100;
  const c = faceValue * (couponRatePct / 100);
  let pvSum = 0;
  let tPvSum = 0;
  for (let t = 1; t <= years; t++) {
    const cf = t === years ? c + faceValue : c;
    const pv = cf / Math.pow(1 + y, t);
    pvSum += pv;
    tPvSum += t * pv;
  }
  const macD = tPvSum / pvSum;
  const modD = macD / (1 + y);
  return {
    macaulayDurationYears: Number(macD.toFixed(2)),
    modifiedDuration: Number(modD.toFixed(2))
  };
}

