  const npv = pvInflows - initialOutlay;
  const npvRound = Number(npv.toFixed(2));
  return {
    npv: npvRound,
    decision: npvRound >= 0 ? 'ACCEPT_PROJECT_WEALTH_MAXIMIZING' : 'REJECT_PROJECT_WEALTH_DESTRUCTION'
