  const pvA = projA.inflows.reduce((s, cf, t) => s + cf / Math.pow(1 + k, t + 1), 0);
  const npvA = Number((pvA - projA.outlay).toFixed(2));
  const pvB = projB.inflows.reduce((s, cf, t) => s + cf / Math.pow(1 + k, t + 1), 0);
  const npvB = Number((pvB - projB.outlay).toFixed(2));
  return {
    optimalProject: npvA >= npvB ? 'PROJECT_A' : 'PROJECT_B',
    npvA,
    npvB,
    deltaNpv: Number(Math.abs(npvA - npvB).toFixed(2))
  };
}

bcom-finance-exam-day-10:
function calculateIRR(initialOutlay, cashInflows, hurdleRatePct) {
  function npv(r) {
    return cashInflows.reduce((s, cf, t) => s + cf / Math.pow(1 + r, t + 1), 0) - initialOutlay;
  }
  let low = -0.5, high = 5.0;
  for (let i = 0; i < 100; i++) {
    const mid = (low + high) / 2;
    if (npv(mid) > 0) low = mid;
    else high = mid;
  }
  const irr = Number(((low + high) / 2 * 100).toFixed(2));
  return {
    irrPercent: irr,
    isViable: irr >= hurdleRatePct
  };
}

bcom-finance-assign-day-10:
function calculateMIRR(initialOutlay, cashInflows, finRate, reinvRate) {
  const n = cashInflows.length;
  const r = reinvRate / 100;
  const tv = cashInflows.reduce((sum, cf, idx) => sum + cf * Math.pow(1 + r, n - 1 - idx), 0);
  const mirr = Math.pow(tv / initialOutlay, 1 / n) - 1;
  return {
    mirrPercent: Number((mirr * 100).toFixed(2))
  };
}

bcom-finance-exam-day-11:
function calculatePaybackPeriod(initialOutlay, cashFlows, discountRatePct = 0) {
  let remSimple = initialOutlay;
  let simpleYears = cashFlows.length;
  let recoveredSimple = false;
  for (let i = 0; i < cashFlows.length; i++) {
    if (remSimple <= cashFlows[i]) {
      simpleYears = i + remSimple / cashFlows[i];
      recoveredSimple = true;
      break;
    }
    remSimple -= cashFlows[i];
  }

  const r = discountRatePct / 100;
  let remDisc = initialOutlay;
  let discYears = cashFlows.length;
  let recoveredDisc = false;
  for (let i = 0; i < cashFlows.length; i++) {
    const pv = cashFlows[i] / Math.pow(1 + r, i + 1);
    if (remDisc <= pv) {
      discYears = i + remDisc / pv;
      recoveredDisc = true;
      break;
    }
    remDisc -= pv;
  }

  return {
    simplePaybackYears: Number(simpleYears.toFixed(2)),
    discountedPaybackYears: Number(discYears.toFixed(2)),
    isRecovered: recoveredSimple
  };
}

bcom-finance-assign-day-11:
function rankProjectsByProfitabilityIndex(projects, budget) {
  const scored = projects.map(p => ({
    ...p,
    pi: p.pvInflows / p.outlay
  })).sort((a, b) => b.pi - a.pi);

  const selected = [];
  let remBudget = budget;
  let totalNpv = 0;
  for (const p of scored) {
    if (p.outlay <= remBudget) {
      selected.push(p);
      remBudget -= p.outlay;
      totalNpv += (p.pvInflows - p.outlay);
    }
  }
  return {
    selectedProjects: selected,
    totalNpvCreated: totalNpv
  };
}

