bcom-finance-exam-day-14:
function calculateWACC(e, d, kePct, kdPrePct, tPct) {
  const v = e + d;
  const we = e / v;
  const wd = d / v;
  const kdAfter = kdPrePct * (1 - tPct / 100);
  const wacc = we * kePct + wd * kdAfter;
  return {
    waccPercent: Number(wacc.toFixed(2)),
    equityWeight: Number(we.toFixed(4)),
    debtWeight: Number(wd.toFixed(4)),
    afterTaxCostOfDebt: Number(kdAfter.toFixed(2))
  };
}

bcom-finance-assign-day-14:
function evaluateWaccUnderLeverage(equitySchedule, debtSchedule, taxPct) {
  let minWacc = Infinity;
  let optDebt = null;
  for (const [rStr, ke] of Object.entries(equitySchedule)) {
    const wd = parseFloat(rStr);
    const we = 1 - wd;
    const kdPre = debtSchedule[rStr];
    const kdAfter = kdPre * (1 - taxPct / 100);
    const wacc = we * ke + wd * kdAfter;
    if (wacc < minWacc) {
      minWacc = wacc;
      optDebt = rStr;
    }
  }
  return {
    optimalDebtRatio: optDebt,
    minimumWacc: Number(minWacc.toFixed(2))
  };
}

bcom-finance-exam-day-15:
function executeCapitalBudgetingMaster(c0, cfs, e, d, kePct, kdPrePct, tPct) {
  const v = e + d;
  const we = e / v;
  const wd = d / v;
  const kdAfter = kdPrePct * (1 - tPct / 100);
  const wacc = we * kePct + wd * kdAfter;
  const pv = cfs.reduce((s, cf, t) => s + cf / Math.pow(1 + wacc / 100, t + 1), 0);
  const npv = pv - c0;
  const pi = pv / c0;
  return {
    calculatedWaccPercent: Number(wacc.toFixed(2)),
    projectNpv: Number(npv.toFixed(2)),
    profitabilityIndex: Number(pi.toFixed(2)),
    isAccepted: npv > 0,
    engineStatus: 'CAPITAL_BUDGETING_WACC_MASTER_ACTIVE'
  };
}

