bcom-finance-exam-day-16:
function calculateLeverages(sales, vc, fc, interest) {
  const contrib = sales - vc;
  const ebit = contrib - fc;
  const ebt = ebit - interest;
  const dol = contrib / ebit;
  const dfl = ebit / ebt;
  const dcl = dol * dfl;
  return {
    contribution: contrib,
    ebit,
    ebt,
    dol: Number(dol.toFixed(2)),
    dfl: Number(dfl.toFixed(2)),
    dcl: Number(dcl.toFixed(2))
  };
}

bcom-finance-assign-day-16:
