bcom-finance-exam-day-17:
function calculateBreakEvenAndMos(fc, p, v, actualUnits) {
  const contrib = p - v;
  const pvRatio = (contrib / p) * 100;
  const bepU = fc / contrib;
  const bepRev = bepU * p;
  const actRev = actualUnits * p;
  const mosRev = actRev - bepRev;
  const mosPct = actRev > 0 ? (mosRev / actRev) * 100 : 0;
  return {
    bepUnits: bepU,
    bepRevenue: bepRev,
    mosRevenue: mosRev,
    mosPercent: Number(mosPct.toFixed(2))
  };
}

bcom-finance-assign-day-17:
