  const reqU = Math.ceil((fc + preTax) / (p - v));
  return {
    requiredUnits: reqU,
    requiredRevenue: reqU * p
  };
}

bcom-finance-exam-day-18:
function generateCashBudget(opening, receipts, payments, minCash = 10000) {
  let curr = opening;
  const closings = [];
  const ods = [];
  for (let i = 0; i < receipts.length; i++) {
    const net = curr + receipts[i] - payments[i];
    if (net < minCash) {
      ods.push(minCash - net);
      closings.push(minCash);
      curr = minCash;
    } else {
      ods.push(0);
      closings.push(net);
      curr = net;
    }
  }
  return {
    monthlyClosingBalances: closings,
    overdraftRequired: ods
  };
}

