    growthRatePercent: Number((g * 100).toFixed(2))
  };
}

bcom-finance-exam-day-21:
function executeCorporatePolicyMaster(ebit, interest, debt, taxPct, eps, dps, roiPct, kePct) {
  const ebt = ebit - interest;
  const dfl = Number((ebit / ebt).toFixed(2));
  const ts = Number((debt * (taxPct / 100)).toFixed(2));
  const walter = Number(((dps + (roiPct / kePct) * (eps - dps)) / (kePct / 100)).toFixed(2));
  return {
    degreeOfFinancialLeverage: dfl,
    capitalizedTaxShield: ts,
    walterTheoreticalPrice: walter,
    engineStatus: 'CORPORATE_FINANCIAL_POLICY_MASTER_ACTIVE'
  };
}

bcom-finance-assign-day-21:
function evaluateTradeOffTheoryFirmValue(vu, d, taxPct, pDefault, bCost) {
  const ts = d * (taxPct / 100);
  const distress = (pDefault / 100) * bCost;
  const vl = vu + ts - distress;
  return {
    leveredFirmValue: vl,
    netBenefitOfDebt: ts - distress
  };
}

bcom-finance-exam-day-22:
function calculateEnterpriseAndPeValue(fcffs, gPct, waccPct, netDebt, shares, eps, peMultiple) {
  const wacc = waccPct / 100;
  const g = gPct / 100;
  const pvFcff = fcffs.reduce((s, cf, t) => s + cf / Math.pow(1 + wacc, t + 1), 0);
  const last = fcffs[fcffs.length - 1];
  const tv = (last * (1 + g)) / (wacc - g);
  const pvTv = tv / Math.pow(1 + wacc, fcffs.length);
  const ev = pvFcff + pvTv;
  const eq = ev - netDebt;
  const dcfPrice = eq / shares;
  const pePrice = eps * peMultiple;
  return {
    enterpriseValue: Number(ev.toFixed(2)),
    equityValue: Number(eq.toFixed(2)),
    dcfTargetPricePerShare: Number(dcfPrice.toFixed(2)),
    peComparativePricePerShare: Number(pePrice.toFixed(2))
  };
}

bcom-finance-assign-day-22:
function calculateEvEbitdaTarget(ebitda, multiple, debt, cash, shares) {
  const ev = ebitda * multiple;
  const eq = ev - debt + cash;
  return {
    enterpriseValue: ev,
    equityValue: eq,
    targetPricePerShare: Number((eq / shares).toFixed(2))
  };
}

bcom-finance-exam-day-23:
function calculatePortfolioRiskReturn(w1, r1, s1, w2, r2, s2, rho) {
  const ret = w1 * r1 + w2 * r2;
  const variance = Math.pow(w1 * s1, 2) + Math.pow(w2 * s2, 2) + 2 * w1 * w2 * s1 * s2 * rho;
  const std = Math.sqrt(Math.max(0, variance));
  return {
    portfolioReturn: Number(ret.toFixed(2)),
    portfolioVariance: Number(variance.toFixed(2)),
    portfolioStandardDeviation: Number(std.toFixed(2))
  };
}

bcom-finance-assign-day-23:
function calculateMinimumVarianceWeights(s1, s2, rho) {
  const num = Math.pow(s2, 2) - s1 * s2 * rho;
  const denom = Math.pow(s1, 2) + Math.pow(s2, 2) - 2 * s1 * s2 * rho;
  const w1 = num / denom;
  return {
    weightAsset1: Number(w1.toFixed(4)),
    weightAsset2: Number((1 - w1).toFixed(4))
  };
}

bcom-finance-exam-day-24:
