  const alpha = actualReturn - req;
  let signal = 'FAIRLY_PRICED_HOLD';
  if (alpha > 0) signal = 'UNDERVALUED_BUY';
  else if (alpha < 0) signal = 'OVERVALUED_SELL';
  return {
    capmRequiredReturn: Number(req.toFixed(2)),
    jensenAlpha: Number(alpha.toFixed(2)),
    investmentSignal: signal
  };
}

