    isMoreVolatileThanMarket: pb > 1.0
  };
}

bcom-finance-exam-day-25:
function calculatePerformanceRatios(rp, rf, stdP, betaP, rm) {
  const excess = rp - rf;
  const sharpe = excess / stdP;
  const treynor = excess / betaP;
  const jensen = rp - (rf + betaP * (rm - rf));
  return {
    excessReturn: Number(excess.toFixed(2)),
    sharpeRatio: Number(sharpe.toFixed(2)),
    treynorRatio: Number(treynor.toFixed(2)),
    jensenAlpha: Number(jensen.toFixed(2))
  };
}

bcom-finance-assign-day-25:
function calculateInformationRatio(pReturns, bReturns) {
  const diffs = pReturns.map((r, i) => r - bReturns[i]);
  const mean = diffs.reduce((s, d) => s + d, 0) / diffs.length;
  const variance = diffs.reduce((s, d) => s + Math.pow(d - mean, 2), 0) / diffs.length;
  const te = Math.sqrt(variance);
  const ir = te === 0 ? 0 : mean / te;
  return {
    activeReturn: Number(mean.toFixed(2)),
    trackingError: Number(te.toFixed(2)),
    informationRatio: Number(ir.toFixed(2))
  };
}

bcom-finance-exam-day-26:
function evaluateFuturesAndPutCallParity(s0, k, rPct, t, call) {
  const r = rPct / 100;
  const fut = s0 * Math.exp(r * t);
  const pvK = k * Math.exp(-r * t);
  const put = call + pvK - s0;
  return {
    fairFuturesPrice: Number(fut.toFixed(2)),
    pvOfStrike: Number(pvK.toFixed(2)),
    impliedPutPrice: Number(put.toFixed(2))
  };
}

