  const combined = eA + eT + synergies;
  const postEps = combined / (sA + sNew);
  const change = postEps - preEps;
  const pct = (change / preEps) * 100;
  return {
    preMergerEps: Number(preEps.toFixed(2)),
    postMergerEps: Number(postEps.toFixed(2)),
    isAccretive: change > 0,
    percentageAccretionDilution: Number(pct.toFixed(2))
  };
}

