  const x2 = re / assets;
  const x3 = ebit / assets;
  const x4 = mCap / liab;
  const x5 = sales / assets;
  const z = 1.2 * x1 + 1.4 * x2 + 3.3 * x3 + 0.6 * x4 + 1.0 * x5;
  let zone = 'DISTRESS_ZONE_HIGH_BANKRUPTCY_RISK';
  if (z > 2.99) zone = 'SAFE_ZONE_MINIMAL_DEFAULT_RISK';
  else if (z >= 1.70) zone = 'GRAY_ZONE_MODERATE_DEFAULT_RISK';
  return {
    zScore: Number(z.toFixed(2)),
    creditZone: zone
  };
}

