  const nps = ((promoters - detractors) / npsList.length) * 100;
  const csatGap = perc - exp;
  const avgPorter = porterList.reduce((s, r) => s + r, 0) / porterList.length;
  const isOpportunity = nps >= 30 && csatGap >= 0 && avgPorter <= 3.0;
  return {
    npsScore: Number(nps.toFixed(1)),
    csatGap,
    averagePorterIntensity: Number(avgPorter.toFixed(2)),
    isMarketOpportunity: isOpportunity,
    engineStatus: 'MARKET_RESEARCH_MASTER_ACTIVE_NOMINAL'
  };
}

