    leadRateInterestToDesire: Number(lead.toFixed(2)),
    purchaseRateDesireToAction: Number(sales.toFixed(2)),
    overallConversionPercent: Number(overall.toFixed(4))
  };
}

bcom-marketing-assign-day-14:
function allocatePromoMixBudget(budget, adPct, digitalPct, promoPct, prPct) {
  return {
    advertisingAmount: budget * (adPct / 100),
    digitalAmount: budget * (digitalPct / 100),
    salesPromoAmount: budget * (promoPct / 100),
    prAmount: budget * (prPct / 100),
    isFullyAllocated: (adPct + digitalPct + promoPct + prPct) === 100
  };
}

bcom-marketing-exam-day-15:
function executeGtmMasterKernel(cost, markup, budget, clicks, leads, sales, msp) {
  const rev = sales * msp;
  const gp = rev - (sales * cost);
  const net = gp - budget;
  return {
    revenueGenerated: rev,
    grossProfit: gp,
    netGtmProfit: net,
    isProfitableLaunch: net > 0,
    engineStatus: 'GTM_STRATEGY_MASTER_ACTIVE_NOMINAL'
  };
}

bcom-marketing-assign-day-15:
function calculateMarketShareMetrics(compRev, totalMarket, leaderRev) {
  const abs = (compRev / totalMarket) * 100;
  const rel = compRev / leaderRev;
  return {
    absoluteMarketSharePercent: Number(abs.toFixed(2)),
    relativeMarketShareRatio: Number(rel.toFixed(2)),
    isMarketLeader: compRev >= leaderRev
  };
}

bcom-marketing-exam-day-16:
function calculateServqualGaps(tan, rel, resp, ass, emp) {
  const gTan = tan.p - tan.e;
  const gRel = rel.p - rel.e;
  const gResp = resp.p - resp.e;
  const gAss = ass.p - ass.e;
  const gEmp = emp.p - emp.e;
  const avg = (gTan + gRel + gResp + gAss + gEmp) / 5;
  return {
    tangiblesGap: gTan,
    reliabilityGap: gRel,
    responsivenessGap: gResp,
    assuranceGap: gAss,
    empathyGap: gEmp,
    compositeServqualScore: Number(avg.toFixed(2)),
    serviceQualityTier: avg >= 0 ? 'EXCEEDS_SERVICE_EXPECTATIONS' : 'SERVICE_DEFICIT_DETECTED'
  };
}

bcom-marketing-assign-day-16:
function evaluateServices7PsReadiness(people, physical, process) {
  const score = (people + physical + (10 - process)) / 3;
  const isReady = score >= 7.5;
  return {
    readinessScore: Number(score.toFixed(2)),
    isOperationallyReady: isReady
  };
}

bcom-marketing-exam-day-17:
function evaluateB2bBuyingCenter(init, inf, gate, dec, buy, user) {
  const weighted = init * 0.05 + inf * 0.20 + gate * 0.15 + dec * 0.35 + buy * 0.10 + user * 0.15;
  const approved = weighted >= 7.0 && dec >= 7;
  let reason = 'INSUFFICIENT_CONSENSUS';
  if (weighted >= 7.0 && dec < 7) reason = 'DECIDER_VETO';
  else if (approved) reason = 'DEAL_APPROVED';
  return {
    consensusScore: Number(weighted.toFixed(2)),
    isProcurementApproved: approved,
    gatingReason: reason
  };
}

bcom-marketing-assign-day-17:
function classifyB2bPurchaseType(history, specChanged, priceVar) {
  if (history === 0) return { buyclassCategory: 'NEW_TASK_PURCHASE' };
  if (specChanged || priceVar > 5.0) return { buyclassCategory: 'MODIFIED_REBUY' };
  return { buyclassCategory: 'STRAIGHT_REBUY' };
}

bcom-marketing-exam-day-18:
function calculateBlendedCac(adSpend, salaries, agencyFees, organicUsers, paidUsers) {
  const totalSpend = adSpend + salaries + agencyFees;
  const totalUsers = organicUsers + paidUsers;
  const paidCac = paidUsers > 0 ? Number((adSpend / paidUsers).toFixed(2)) : 0;
  const blendedCac = totalUsers > 0 ? Number((totalSpend / totalUsers).toFixed(2)) : 0;
  const organicShare = totalUsers > 0 ? Number(((organicUsers / totalUsers) * 100).toFixed(2)) : 0;
  return {
    paidCac,
    blendedCac,
    organicAcquisitionSharePercent: organicShare
  };
}

bcom-marketing-assign-day-18:
function calculateRoasAndCpc(spend, clicks, revenue) {
  return {
    costPerClick: Number((spend / clicks).toFixed(2)),
    returnOnAdSpend: Number((revenue / spend).toFixed(2)),
    isProfitableCampaign: (revenue / spend) > 1.0
  };
}

bcom-marketing-exam-day-19:
function calculateCustomerLifetimeValue(aov, freq, marginPct, churnPct) {
  const profit = aov * freq * (marginPct / 100);
  const churn = churnPct / 100;
  const clv = profit / churn;
  const life = 1 / churn;
  return {
    annualCustomerProfit: Number(profit.toFixed(2)),
    customerLifetimeValue: Number(clv.toFixed(2)),
    averageLifespanYears: Number(life.toFixed(1))
  };
}

bcom-marketing-assign-day-19:
function evaluateClvToCacRatio(clv, cac) {
  const ratio = clv / cac;
  let status = 'VALUE_DESTRUCTION_ALERT';
  if (ratio >= 3.0) status = 'HEALTHY_EXPANSION_GRADE';
  else if (ratio >= 1.0) status = 'MARGINAL_UNIT_ECONOMICS';
  return {
    clvToCacRatio: Number(ratio.toFixed(2)),
    unitEconomicsStatus: status
  };
}

bcom-marketing-exam-day-20:
function calculateRomi(incRev, marginPct, mktExp) {
  const gp = incRev * (marginPct / 100);
  const net = gp - mktExp;
  const romi = (net / mktExp) * 100;
  return {
    grossMarginFromCampaign: Number(gp.toFixed(2)),
    netProfitAttributed: Number(net.toFixed(2)),
    romiPercent: Number(romi.toFixed(2)),
    isPositiveReturn: romi > 0
  };
}

bcom-marketing-assign-day-20:
function calculateMcosEfficiency(budget, revenue) {
  const mcos = (budget / revenue) * 100;
  return {
    marketingCostOfSalesPercent: Number(mcos.toFixed(2)),
    isEfficientMarketingExpenditure: mcos <= 15.0
  };
}

bcom-marketing-exam-day-21:
function executeEnterpriseMarketingEngine(gaps, b2bRate, cac, clv, romi) {
  const avgGap = gaps.reduce((s, g) => s + g, 0) / gaps.length;
  const clvToCac = clv / cac;
  const isHealthy = avgGap >= 0 && clvToCac >= 3.0 && romi > 0;
  return {
    averageServqualGap: Number(avgGap.toFixed(2)),
    clvToCacRatio: Number(clvToCac.toFixed(2)),
    isEnterpriseMarketingCompliant: isHealthy,
    engineStatus: 'ENTERPRISE_MARKETING_PERFORMANCE_MASTER_ACTIVE'
  };
}

bcom-marketing-assign-day-21:
function aggregateMarketingScorecard(brand, leads, ret, roi) {
  const score = brand * 0.20 + leads * 0.30 + ret * 0.25 + roi * 0.25;
  return {
    compositeScore: Number(score.toFixed(2)),
    isTopTierPerformance: score >= 80
  };
}

bcom-marketing-exam-day-22:
function calculateViralKFactor(invitesPerUser, conversionPct) {
  const k = invitesPerUser * (conversionPct / 100);
  const isExp = k > 1.0;
  return {
    kFactor: Number(k.toFixed(2)),
    isExponentialGrowth: isExp,
    growthStatus: isExp ? 'EXPONENTIAL_SELF_SUSTAINING_VIRAL_LOOP' : 'AMPLIFIED_SUB_CRITICAL_GROWTH'
  };
}

bcom-marketing-assign-day-22:
function calculateViralCustomerMultiplier(initialUsers, k, cycles) {
  let total = 0;
  if (k < 1.0) {
    total = initialUsers / (1 - k);
  } else {
    let curr = initialUsers;
    for (let c = 0; c <= cycles; c++) {
      total += curr;
      curr = curr * k;
    }
  }
  return {
    projectedTotalUsers: Math.round(total),
    isConvergent: k < 1.0
  };
}

bcom-marketing-exam-day-23:
function evaluateDecoyPricingEffect(pA, qA, pB, qB, pDecoy, shiftPct) {
  const baseRev = pA * qA + pB * qB;
  const shifted = qA * (shiftPct / 100);
  const newQA = qA - shifted;
  const newQB = qB + shifted;
  const newRev = pA * newQA + pB * newQB;
  const lift = newRev - baseRev;
  const pct = baseRev > 0 ? (lift / baseRev) * 100 : 0;
  return {
    baselineRevenue: baseRev,
    newRevenueWithDecoy: newRev,
    revenueLift: Number(lift.toFixed(2)),
    percentageLift: Number(pct.toFixed(2))
  };
}

bcom-marketing-assign-day-23:
function calculateAnchoringUtility(anchorPrice, salePrice, cost) {
  const perceivedSavings = anchorPrice - salePrice;
  const discountPct = (perceivedSavings / anchorPrice) * 100;
  const merchantProfit = salePrice - cost;
  return {
    perceivedSavingsAmount: perceivedSavings,
    perceivedDiscountPercent: Number(discountPct.toFixed(2)),
    merchantProfitMargin: merchantProfit,
    isProfitableSale: merchantProfit > 0
  };
}

bcom-marketing-exam-day-24:
function calculateInterbrandValuation(intangibleEarnings, robiPct, discountRatePct) {
  const brandEarnings = intangibleEarnings * (robiPct / 100);
  const discount = discountRatePct / 100;
  const brandValue = brandEarnings / discount;
  return {
    brandedEconomicEarnings: Number(brandEarnings.toFixed(2)),
    netBrandValue: Number(brandValue.toFixed(2)),
    brandEquityStatus: brandValue >= 1000000 ? 'MEGA_BRAND_TIER_A' : 'NICHE_VALUATION_TIER_B'
  };
}

bcom-marketing-assign-day-24:
function calculateRoyaltyReliefBrandValue(revenues, royaltyPct, taxPct, discountPct) {
  const r = discountPct / 100;
  const t = taxPct / 100;
  const pvTotal = revenues.reduce((sum, rev, idx) => {
    const royalty = rev * (royaltyPct / 100) * (1 - t);
    return sum + royalty / Math.pow(1 + r, idx + 1);
  }, 0);
  return {
    capitalizedBrandValue: Number(pvTotal.toFixed(2))
  };
}

bcom-marketing-exam-day-25:
function evaluateEprgOrientation(ethno, poly, regio, geo) {
  const scores = { ETHNOCENTRIC: ethno, POLYCENTRIC: poly, REGIOCENTRIC: regio, GEOCENTRIC: geo };
  const dominant = Object.keys(scores).reduce((a, b) => scores[a] > scores[b] ? a : b);
  let strat = 'STANDARDIZED_CENTRALIZED_HOME_BASE';
  if (dominant === 'GEOCENTRIC') strat = 'TRUE_GLOCAL_INTEGRATED_NETWORK';
  else if (dominant === 'POLYCENTRIC') strat = 'MULTIDOMESTIC_DECENTRALIZED';
  return {
    dominantOrientation: dominant,
    glocalizationIndex: Number(((geo + poly) / 2).toFixed(2)),
    globalStrategyType: strat
  };
}

bcom-marketing-assign-day-25:
function calculateExportPriceEscalation(msp, tariffPct, freight, fxRate) {
  const landed = (msp + freight) * (1 + tariffPct / 100);
  const foreign = landed * fxRate;
  return {
    domesticLandedCost: Number(landed.toFixed(2)),
    foreignRetailPrice: Number(foreign.toFixed(2))
  };
}

bcom-marketing-exam-day-26:
function evaluateCrisisSeverity(customers, mediaReach, faultLevel) {
  const score = Math.min(100, Math.round((customers / 1000000) * 30 + (mediaReach / 1000000) * 30 + faultLevel * 40));
  let strat = 'DENIAL_OR_BOLSTERING_REMIND_OF_PAST_GOODWILL';
  if (score >= 75) strat = 'REBUILDING_STRATEGY_FULL_APOLOGY_AND_COMPENSATION';
  else if (score >= 40) strat = 'DIMINISHMENT_STRATEGY_EXCUSE_AND_JUSTIFICATION';
  return {
    crisisSeverityScore: score,
    recommendedScctStrategy: strat,
    isCriticalReputationalEmergency: score >= 75
  };
}

bcom-marketing-assign-day-26:
function calculateAvePrValue(mediaUnits, adRate, multiplier = 3.0) {
  const base = mediaUnits * adRate;
  return {
    rawAdvertisingEquivalent: base,
    earnedPrMediaValue: base * multiplier
  };
}

bcom-marketing-exam-day-27:
function auditGreenwashingRisk(hasCert, isVague, lacksProof, tradeOff) {
  let risk = 0;
  if (!hasCert) risk++;
  if (isVague) risk++;
  if (lacksProof) risk++;
  if (tradeOff) risk++;
  let status = 'AUTHENTIC_VERIFIED_SUSTAINABLE_CLAIM';
  if (risk > 2) status = 'HIGH_REGULATORY_GREENWASHING_PENALTY_RISK';
  else if (risk > 0) status = 'MODERATE_GREENWASHING_AUDIT_EXPOSURE';
  return {
    detectedGreenwashingViolationsCount: risk,
    claimAuditStatus: status,
    isLegallyCompliant: risk === 0
  };
}

bcom-marketing-assign-day-27:
function calculateGreenPackagingMetrics(ecoCost, stdCost, carbonRed, wtp) {
  const delta = ecoCost - stdCost;
  const pct = Number(((delta / stdCost) * 100).toFixed(2));
  return {
    costIncreasePercent: pct,
    isCommerciallyViable: wtp >= pct
  };
}

bcom-marketing-exam-day-28:
function calculateAiLeadScore(firmo, events, recencyHours, intent) {
  const score = Math.min(100, Math.max(0, Math.round(firmo * 0.30 + Math.min(30, events * 3) + Math.max(0, 20 - recencyHours * 0.5) + intent * 0.20)));
  let routing = 'COLD_LEAD_MARKETING_QUALIFIED_LIST';
  if (score >= 80) routing = 'HOT_LEAD_IMMEDIATE_SALES_REP_ENGAGEMENT';
  else if (score >= 50) routing = 'WARM_LEAD_AUTOMATED_NURTURE_DRIP';
  return {
    compositeAiLeadScore: score,
    automatedRoutingAction: routing
  };
}

bcom-marketing-assign-day-28:
function calculateAbTestLift(ctrlVis, ctrlConv, varVis, varConv) {
  const crA = (ctrlConv / ctrlVis) * 100;
  const crB = (varConv / varVis) * 100;
  const lift = ((crB - crA) / crA) * 100;
  return {
    controlConversionRatePercent: Number(crA.toFixed(2)),
    variantConversionRatePercent: Number(crB.toFixed(2)),
    relativeConversionLiftPercent: Number(lift.toFixed(2)),
    isVariantWinning: lift > 0
  };
}

bcom-marketing-exam-day-29:
function auditAdCompliance(substantiated, clearDisclosures, pufferyOk, isSurrogate) {
  const ok = Boolean(substantiated && clearDisclosures && pufferyOk && !isSurrogate);
  let risk = 'NONE_APPROVED_FOR_BROADCAST';
  if (isSurrogate) risk = 'SEVERE_SURROGATE_AD_STATUTORY_BAN';
  else if (!ok) risk = 'REGULATORY_SHOW_CAUSE_NOTICE_RISK';
  return {
    isAdApprovedForPublicRelease: ok,
    regulatoryRiskRating: risk
  };
}

bcom-marketing-assign-day-29:
function validateDataPrivacyConsent(optIn, forgetHonored, noticeShown) {
  const ok = Boolean(optIn && forgetHonored && noticeShown);
  return {
    isDataPrivacyCompliant: ok,
    privacyRiskTier: ok ? 'GDPR_DPDP_COMPLIANT' : 'CRITICAL_DATA_PRIVACY_VIOLATION'
  };
}

bcom-marketing-exam-day-30:
function orchestrateCorporateMarketing(research, stp, gtm, digital, global, score = 100) {
  const ok = Boolean(research && stp && gtm && digital && global && score >= 85);
  return {
    marketResearchCertified: research,
    stpFrameworkValidated: stp,
    gtmStrategyExecuted: gtm,
    digitalPerformanceActive: digital,
    globalMarketingAligned: global,
    cmoEnterpriseCertified: ok,
    compositeBrandScore: score,
    status: ok ? 'CORPORATE_MARKETING_AND_GLOBAL_BRAND_MASTER_CERTIFIED_NOMINAL' : 'MARKETING_STRATEGY_DEFECT_AUDIT_HALTED'
  };
}

bcom-marketing-assign-day-30:
function computeCmoDashboardHealth(romi, nps, clvCac, brandGrowth) {
  const ok = romi >= 50 && nps >= 30 && clvCac >= 3.0 && brandGrowth > 0;
  return {
    isCorporateMarketingHealthy: ok,
    executiveDashboardGrade: ok ? 'GRADE_A_EXCELLENCE' : 'REMEDIATION_REQUIRED'
  };
}
